contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive sequence: call SetMinSum before and after Initialized and observe revert behavior
    // params: val - value to set; preSucceeds - whether the first call is expected to succeed (should be true on P)
    // We use low-level calls to detect whether SetMinSum reverted.
    function run(uint val) public {
        // First attempt: before Initialized, SetMinSum should NOT revert on original contract.
        (bool ok1, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", val));

        // Now call Initialized to flip the flag
        c.Initialized();

        // Second attempt: after Initialized, SetMinSum should revert on original contract.
        (bool ok2, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", val));

        // Property: the first call succeeds and the second call fails.
        // This distinguishes P (ok1==true, ok2==false) from M which inverts the guard.
        assert(ok1 && !ok2);
    }
}

