    function testFuzz_property(address addr, bool doInit) public {
        // keep addr non-zero to be meaningful
        if (addr == address(0)) addr = address(1);

        // 1) optionally initialize the contract based on fuzzed boolean
        if (doInit) {
            // any caller can call Initialized()
            c.Initialized();
        }

        // 2) call SetLogFile with the fuzzed address
        // capture whether the call succeeded (reference always allows call; mutant may differ in semantics by changing Log even after init)
        bool ok;
        try c.SetLogFile(addr) {
            ok = true;
