        // 3) The universal property for the reference: after calling SetLogFile, the public Log getter (address) equals the passed address iff the contract was NOT initialized before the call.
        // We assert that property by observing c.Log() and doInit.
        // For the correct contract, when doInit==true, SetLogFile should revert (ok==false) OR should leave Log unchanged (i.e., not equal to addr).
        // When doInit==false, SetLogFile should succeed (ok==true) and Log()==addr.

        // Build observed fact: current Log value
        address observed = address(c.Log());

