contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor address and amounts/lockTimes
    function testFuzz_property(address actor, uint256 initialFund, uint256 putValue, uint256 lockTime, uint256 collectAmt) public {
        // keep addresses useful
        vm.assume(actor != address(0));
        // keep values bounded to avoid overflow in test harness but allow zero
        initialFund = bound(initialFund, 0, 1 ether);
        putValue = bound(putValue, 0, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);
        lockTime = bound(lockTime, 0, 1000000);

        // fund the actor so they can send ETH
        vm.deal(actor, initialFund + putValue + collectAmt);

        // Actor performs an initial Put with some value (maybe zero) to set up account
        vm.prank(actor);
        // call Put with putValue; may be zero
        c.Put{value: putValue}(lockTime);

        // record balance before Collect (via public getter Acc(address).balance)
        (uint beforeUnlockTime, uint beforeBalance) = getHolder(actor);

        // attempt Collect: use try/catch to capture revert differences
        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // read after state
        (uint afterUnlockTime, uint afterBalance) = getHolder(actor);

        // General invariant: Collect never increases recorded balance for the caller
        // i.e., afterBalance <= beforeBalance
        // This holds for the reference implementation for all inputs, but the mutant
        // that forbids zero-value puts can change allowed sequences and cause differences
        assertTrue(afterBalance <= beforeBalance);
    }

    // helper to read the public struct fields via the auto-generated getter signature
    function getHolder(address a) internal returns (uint, uint) {
        // The compiler generates Acc(address) returns (uint unlockTime, uint balance)
        (uint ut, uint bal) = c.Acc(a);
        return (ut, bal);
    }
}
